const setMeta=(selector,attribute,value)=>{let element=document.head.querySelector(selector);if(!element){element=document.createElement(selector.startsWith('link')?'link':'meta');document.head.append(element)}element.setAttribute(attribute,value)};
function applySeo(path){const meta=seoRoutes[path]||seoRoutes['/'];const canonical=`https://familychronica.com${path==='/'?'/':path}`;document.title=meta.title;setMeta('meta[name="description"]','content',meta.description);setMeta('meta[name="robots"]','content',meta.noindex?'noindex, nofollow':'index, follow, max-image-preview:large');setMeta('meta[property="og:title"]','content',meta.title);setMeta('meta[property="og:description"]','content',meta.description);setMeta('meta[property="og:url"]','content',canonical);setMeta('meta[name="twitter:card"]','content','summary_large_image');setMeta('meta[name="twitter:title"]','content',meta.title);setMeta('meta[name="twitter:description"]','content',meta.description);document.querySelector('link[rel="canonical"]')?.setAttribute('href',canonical)}

