function clientShowcase(){return `<section class="section client-showcase"><div class="section-heading"><div><span class="eyebrow">Inside FamilyChronica</span><h2>A calm place for a family's whole story.</h2></div><p>The client brings timelines, photographs, interviews, books, and family members together without turning memories into a complicated database.</p></div><div class="client-layout"><div class="client-copy"><div class="client-tabs" role="tablist"><button class="client-tab active" data-client-screen="timeline"><span>01</span>Family timeline</button><button class="client-tab" data-client-screen="photos"><span>02</span>Smart albums</button><button class="client-tab" data-client-screen="interview"><span>03</span>Guided interview</button><button class="client-tab" data-client-screen="books"><span>04</span>Living books</button></div><div class="client-detail"><span id="clientLabel">THE FAMILY HOME</span><h3 id="clientTitle">See the people and moments that shaped you.</h3><p id="clientText">The opening screen is a story-led family timeline with quick ways to record a voice, add a photograph, invite someone, or preview the annual book.</p><a id="clientLink" class="text-button" href="/features" data-link>Explore the product →</a></div></div><div class="app-device"><div class="app-status"><span>9:41</span><span>●●●　Wi-Fi</span></div><div class="app-screen" id="appScreen"><div class="app-top"><div><small>Johnston Family · 23 members</small><b>FamilyChronica</b></div><button>MJ</button></div><div class="app-progress"><i></i></div><h3>Keep each other's stories<br>for the family ahead.</h3><div class="quick-actions"><span>●<small>Voice</small></span><span>▧<small>Photos</small></span><span>▶<small>Video</small></span><span>＋<small>Invite</small></span></div><div class="app-year">2026 · FAMILY TIMELINE</div><article class="app-story"><div class="story-thumb coral">▶</div><div><b>Grandma's 90th birthday</b><small>August 15 · 12 family contributors</small><em>Play film · 03:42</em></div></article><article class="app-story"><div class="story-thumb green">♪</div><div><b>Grandpa's old London</b><small>June 12 · Story draft reviewed</small><em>Continue listening · 52%</em></div></article></div><nav class="app-nav"><span>⌂<small>Home</small></span><span>♧<small>Family</small></span><span class="app-record">＋<small>Record</small></span><span>▤<small>Books</small></span><span>○<small>Me</small></span></nav></div></div></section>`}

function commercialHome(){return `${clientShowcase()}
  <section class="section intent-section"><div class="section-heading"><div><span class="eyebrow">Begin where you are</span><h2>One service, made for three generations.</h2></div><p>Record your own life, help a parent begin, or invite the whole family into one carefully managed archive.</p></div><div class="intent-grid"><a href="/for-parents" data-link class="intent-item"><span>For a parent</span><h3>Help me preserve their stories</h3><p>Set up the chronicle, send gentle prompts, and assist from anywhere.</p><strong>Explore parent support →</strong></a><a href="/signup" data-link class="intent-item"><span>For myself</span><h3>I want to tell my story</h3><p>Speak naturally. Pause anytime. Review every word before sharing.</p><strong>Record a first memory →</strong></a><a href="/for-families" data-link class="intent-item"><span>For our family</span><h3>Build it together</h3><p>Invite relatives with clear roles, privacy settings, and approvals.</p><strong>See family collaboration →</strong></a></div></section>
  <section class="section product-journey"><div class="section-heading"><div><span class="eyebrow">One memory's journey</span><h2>From a voice to a chapter.</h2></div><div class="journey-tabs" role="tablist"><button class="journey-tab active" data-journey="speak">1 Speak</button><button class="journey-tab" data-journey="shape">2 Shape</button><button class="journey-tab" data-journey="place">3 Place</button><button class="journey-tab" data-journey="print">4 Print</button></div></div><div class="journey-stage"><div class="journey-copy"><span id="journeyKicker">A quiet prompt</span><h3 id="journeyTitle">“What did home feel like when you were ten?”</h3><p id="journeyText">Tap once and answer in your own words. There is no timer and no perfect way to tell it.</p><div class="permission-note">You review and approve every AI-assisted edit.</div></div><div class="chronicle-preview"><div class="preview-bar"><span>The Johnston Chronicle</span><span>Draft · Private</span></div><div class="audio-wave" aria-label="Audio waveform"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p class="preview-label">Mary's voice · 4 min 18 sec</p><h4>Sunday mornings on Willow Street</h4><p id="previewExcerpt">The kitchen was the center of our small house. Before anyone else woke, my mother would open the window above the sink and begin the cinnamon rolls.</p><div class="memory-tags"><span>Mary Johnston</span><span>1958</span><span>Chicago</span></div></div></div></section>
  <section class="section section-paper book-detail"><div class="book-spread"><div class="book-page"><small>THE JOHNSTON FAMILY · 1958</small><h3>Sunday mornings on Willow Street</h3><div class="book-photo"></div><p>The kitchen was the center of our small house. It held the sounds and scents by which we measured the week.</p><span class="page-no">84</span></div><div class="book-page book-page-right"><blockquote>“We did not know we were making memories. We were simply home.”</blockquote><div class="mini-photos"><span></span><span></span></div><span class="page-no">85</span></div></div><div class="book-spec"><span class="eyebrow">A book worth keeping</span><h2>Designed in your browser. Approved by your family.</h2><p>Preview the cover and every page before printing. Choose your title, family name, photographs, dedication, and edition.</p><dl><div><dt>Format</dt><dd>Hardcover, lay-flat friendly</dd></div><div><dt>Contents</dt><dd>Stories, photographs, tree & media index</dd></div><div><dt>Versions</dt><dd>Every edition remains available</dd></div></dl><a class="button" href="/sample-book" data-link>Explore a sample book</a></div></section>
  <section class="section trust-home"><div class="section-heading"><div><span class="eyebrow">Trust is part of the product</span><h2>Your family's story stays in your family's hands.</h2></div><a class="text-button" href="/security" data-link>Visit the Trust Center →</a></div><div class="trust-grid"><article><strong>01</strong><h3>You own the story</h3><p>Your recordings, photographs, and generated chronicle remain yours. Export your archive in common formats.</p></article><article><strong>02</strong><h3>AI suggests. You decide.</h3><p>See the original transcript, review changes, correct facts, and approve what becomes part of the book.</p></article><article><strong>03</strong><h3>Privacy by memory</h3><p>Keep a memory private, share it with selected relatives, or include it in the family edition.</p></article><article><strong>04</strong><h3>Human help when needed</h3><p>Family assistance and support are available without taking control away from the storyteller.</p></article></div></section>
  <section class="section section-dark faq-section"><div class="section-heading"><div><span class="eyebrow">Questions families ask first</span><h2>Clear before you begin.</h2></div><a href="/support" data-link class="button button-light">See all help topics</a></div><div class="faq-list">${[['Does AI change what my parent said?','It creates an optional, editable narrative from the transcript. The original recording and transcript remain available, and nothing is published without review.'],['Can family members see everything?','No. Each memory can be private, shared with selected people, or visible to the family. Roles determine who may edit or approve content.'],['What happens if I cancel?','You can export your archive. The exact retention and deletion schedule is shown before cancellation and in the Privacy Center.'],['When is the annual book printed?','You receive a preview and approval step before production. You can also order any saved edition from the Store.']].map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}<span>+</span></summary><p>${x[1]}</p></details>`).join('')}</div></section>${contactChannels()}`}

