pages['/about'] = () => `${hero('Why we began','History remembers the famous. We remember each other.','FamilyChronica began with a box of photographs, a fading voice recording, and the realization that ordinary lives are never ordinary to the people who love them.')}
<section class="section"><div class="section-heading"><div><span class="eyebrow">Our mission</span><h2>Make remembrance simple enough for everyone.</h2></div><p>We use careful technology to lower the barrier to family history — especially for older adults whose stories are most at risk of being lost.</p></div><div class="value-grid"><article class="value-item"><span class="value-number">BELONGING</span><h3>Family-made</h3><p>No outside narrator knows your family better than the people within it.</p></article><article class="value-item"><span class="value-number">DIGNITY</span><h3>Your voice remains yours</h3><p>AI supports the story. It never replaces the character, language, or meaning of the speaker.</p></article><article class="value-item"><span class="value-number">STEWARDSHIP</span><h3>Built to outlast us</h3><p>Clear ownership, exportable archives, version history, and durable printed editions.</p></article></div></section>${cta()}`;

