const newsroomCard=item=>`<a class="news-card" href="${item.path}" data-link><img src="${item.image}" alt="${item.title}"><div><span class="eyebrow">${item.label} · SEPTEMBER 4, 2026</span><h2>${item.title}</h2><p>${item.summary}</p><strong>Read the announcement →</strong></div></a>`;
const pressRelease=(item,body)=>`<article class="press-release"><header class="press-header"><a href="/news" data-link>← Newsroom</a><span class="eyebrow">${item.label}</span><h1>${item.title}</h1><p>${item.summary}</p><div class="press-meta"><time datetime="2026-09-04">September 4, 2026</time><span>Press release</span></div></header><img class="press-hero" src="${item.image}" alt="${item.title}"><div class="press-layout"><aside><strong>Media contact</strong><a href="mailto:hello@familychronica.com">hello@familychronica.com</a><a href="https://familychronica.com">familychronica.com</a></aside><div class="press-body"><strong class="release-note">FOR IMMEDIATE RELEASE</strong>${body}<figure class="press-video"><video controls playsinline preload="metadata" poster="${item.image}"><source src="${item.video}?v=20260905.1" type="video/mp4">Your browser does not support HTML video.</video><figcaption>FamilyChronica narrated story film · approximately 5 minutes</figcaption></figure><h2>About FamilyChronica</h2><p>FamilyChronica is a voice-first family memory service designed to help families record stories, organize photographs and videos, collaborate across generations, and shape approved memories into a lasting digital chronicle and printed editions. Family members remain in control of what they contribute and share.</p><div class="press-end">###</div></div></div></article>${cta()}`;

pages['/news']=()=>`<section class="newsroom-hero"><span class="eyebrow">FAMILYCHRONICA NEWSROOM</span><h1>News, ideas, and milestones worth preserving.</h1><p>Product announcements and perspectives on helping families keep the voices and context behind their history.</p></section><section class="newsroom-list">${newsItems.map(newsroomCard).join('')}</section><section class="press-contact"><div><span class="eyebrow">MEDIA ENQUIRIES</span><h2>Writing about family memory, responsible AI, or digital legacy?</h2></div><a class="button" href="mailto:hello@familychronica.com">Contact the press team</a></section>`;

pages['/news/voice-first-family-archive']=()=>pressRelease(newsItems[0],`<p><strong>UNITED STATES</strong> — FamilyChronica today announced early access to its voice-first family memory platform for families in the United States, United Kingdom, Canada, and Australia.</p><p>Unlike traditional family-tree software, FamilyChronica begins with conversation. Parents and grandparents can answer gentle questions in their own voices, while invited family members add photographs, videos, names, dates, and their own memories.</p><p>Recordings can be transcribed and organized with AI assistance, while the original voice remains preserved and families review changes before a story becomes part of their chronicle.</p><blockquote>“Families often inherit photographs without the voices and stories that explain them. We want to make recording those stories feel as natural as having a conversation at the kitchen table.”</blockquote><p>FamilyChronica is being designed around private family spaces, controlled invitations, memory-level permissions, and exportable family archives. Families can gradually shape their contributions into a searchable timeline and lasting family history editions.</p><h2>One story is enough to begin</h2><p>The early experience focuses on a simple first action: asking one meaningful question and preserving the answer. A family can then invite relatives to add context, connect media, and review the story together.</p><p>Early access is available at <a href="/app" data-link>familychronica.com/app</a>.</p>`);

pages['/news/every-photograph-has-a-story']=()=>pressRelease(newsItems[1],`<p><strong>UNITED STATES</strong> — FamilyChronica today introduced a guided way for families to reconnect old photographs with the stories that make them meaningful.</p><p>Albums often survive longer than the names, places, dates, and voices behind them. FamilyChronica lets a family member add a photograph, ask relatives what they remember, and preserve each contribution alongside the image.</p><p>The experience supports photographs, scanned prints, voice recordings, and video. Suggested people, places, and dates are intended to be reviewed by the family before they become part of its shared history.</p><blockquote>“A photograph shows us what happened. A familiar voice can tell us why it mattered.”</blockquote><p>Different relatives do not always remember an event in the same way. Rather than forcing one definitive version, FamilyChronica is designed to preserve attributed perspectives and let families decide how each memory should be shared.</p><h2>From unidentified image to family chapter</h2><p>A photograph can become the beginning of a richer record: who appears in it, where it was taken, what happened before and after, and how different people remember the day. Approved memories can later appear in a family timeline, album, or printed chronicle.</p><p>Families can request early access at <a href="/app" data-link>familychronica.com/app</a>.</p>`);

pages['/news/one-family-history-across-distance']=()=>pressRelease(newsItems[2],`<p><strong>UNITED STATES</strong> — FamilyChronica today announced an early family collaboration experience designed for relatives who live across cities, countries, and time zones.</p><p>One person can begin a private family space and invite parents, grandparents, siblings, and extended relatives to contribute in the format that feels most natural to them. Contributions may include spoken memories, written notes, photographs, scanned documents, and video.</p><p>Each memory is designed to have its own audience and review state. A private contribution does not need to become visible to the entire family, and an invited relative does not automatically receive control of the whole archive.</p><blockquote>“Distance should not decide which family stories survive. A shared archive can bring contributions together without flattening every person’s voice into one version.”</blockquote><p>FamilyChronica also supports multilingual families by keeping source recordings and family-reviewed text together. This helps future generations hear the original speaker while reading an accessible version of the story.</p><h2>Built around contribution, not constant chat</h2><p>The product centers discussion around a memory, photograph, or question so valuable family context can become part of the archive instead of disappearing in an endless message stream.</p><p>Early access is open at <a href="/app" data-link>familychronica.com/app</a>.</p>`);

pages['/support'] = () => `${hero('Help Center & FAQ','A clear answer is never far away.','Find answers about recording, family access, AI assistance, printed books, billing, privacy, and account recovery.')}
<section class="section support-faq"><div class="faq-category"><span class="eyebrow">Getting started</span><div class="faq-list light-faq">${[['Can my parent use it alone?','Yes. Large controls, voice-first recording, passwordless email sign-in, and one focused task at a time are designed for independent use.'],['Can I create the account for a parent?','Yes. You can create a family, invite your parent, and help them begin. Assistance access should remain visible and revocable.'],['Do we need to record everything at once?','No. Interviews save progress after each question and a storyteller can return whenever they are ready.']].map((x,i)=>`<details ${i===0?'open':''}><summary>${x[0]}<span>+</span></summary><p>${x[1]}</p></details>`).join('')}</div></div><div class="faq-category"><span class="eyebrow">AI & privacy</span><div class="faq-list light-faq">${[['Does AI rewrite the facts?','AI creates an editable suggestion. Your recording and transcript remain available, and the family reviews names, dates, meaning, and visibility before approval.'],['Can every family member see every memory?','No. Each story and album can have its own audience. Roles also determine who may contribute, edit, approve books, or manage access.'],['Can I turn off photo recognition?','Yes. Album settings are designed to control person and place suggestions, original downloads, and generated labels.']].map(x=>`<details><summary>${x[0]}<span>+</span></summary><p>${x[1]}</p></details>`).join('')}</div></div><div class="faq-category"><span class="eyebrow">Books & subscription</span><div class="faq-list light-faq">${[['When is the annual book printed?','You receive a complete preview and approval step before production. A saved historical edition can also be ordered later.'],['Can we correct an older story?','Yes. The living digital chronicle can be updated while previous book versions remain available for comparison and reprint.'],['What happens if I cancel?','The commercial service will provide an archive export path and show the verified retention schedule before cancellation.']].map(x=>`<details><summary>${x[0]}<span>+</span></summary><p>${x[1]}</p></details>`).join('')}</div></div><div class="faq-category"><span class="eyebrow">Account access</span><div class="faq-list light-faq">${[['I did not receive a sign-in code. What should I do?','Check the email address and spam folder, request a new code, then contact accounts@familychronica.com if it still does not arrive.'],['Who can change the family owner?','Ownership transfer must be confirmed through a protected account process. Contact accounts@familychronica.com for recovery or succession help.'],['Where do I ask a general product question?','Write to support@familychronica.com. Brand, partnership, and press enquiries should go to hello@familychronica.com.']].map(x=>`<details><summary>${x[0]}<span>+</span></summary><p>${x[1]}</p></details>`).join('')}</div></div></section>${contactChannels()}`;

