function showToast(message){toast.textContent=message;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
async function apiRequest(path,options={}){const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||'Something went wrong');return data}
const optionChoices={'Page count':['80 pages','120 pages','200 pages','Custom'],'Cover material':['Archival linen','Vegan leather','Full-grain leather'],'Binding':['Hardcover','Lay-flat hardcover','Hand-sewn'],'Paper':['Archival natural','Premium matte','Photo-grade'],'Language':['English','Simplified Chinese','Bilingual','Custom'],'Number of copies':['1 copy','2 copies','5 copies','10 copies'],'Album size':['Square','Landscape','Large format'],'Photo count':['Up to 100','Up to 250','Up to 500','Custom'],'Recording length':['60 minutes','90 minutes','120 minutes','Custom'],'Tape count':['1 tape','2 tapes','Boxed set'],'Case style':['Archival case','Presentation box','Custom family case'],'Label design':['Classic','Photo label','Custom'],'Digital backup':['Included download','Encrypted cloud copy','No digital copy'],'Runtime':['60 minutes','120 minutes','240 minutes','Custom'],'Tape format':['VHS archive edition','Modern digital tape edition'],'Disc type':['Archival DVD','Archival Blu-ray','M-DISC'],'Capacity':['32GB','64GB','128GB','256GB'],'Archive index':['PDF index','Interactive HTML index','Both'],'Material':['Brushed metal','Walnut wood','Recycled aluminum'],'Presentation box':['Standard case','Linen box','Walnut box'],'Encryption':['Password protected','Hardware encrypted'],'Photo count':['Up to 100','Up to 250','Up to 500','Custom']};
async function loadStoreAccess(){
  if(location.pathname!=='/store')return;
  try{
    const session=await apiRequest('/api/auth/session');if(!session.authenticated)return;
    const {catalog}=await apiRequest('/api/store/catalog');
    catalog.plans.forEach(plan=>{
      const card=document.querySelector(`[data-catalog-id="${plan.id}"]`);if(!card)return;
      const price=card.querySelector('.store-price');price.classList.add('unlocked');price.innerHTML=`<span>Private quotation</span><strong>${plan.price}</strong>`;
      card.querySelector('.store-access')?.remove();
      const details=document.createElement('details');details.className='store-config';details.innerHTML=`<summary>Choose this edition</summary><form>${plan.options.map((label,index)=>`<label>${label}<select name="option-${index}">${(optionChoices[label]||['Standard','Premium','Custom']).map(value=>`<option>${value}</option>`).join('')}</select></label>`).join('')}<button class="button" type="submit">Save my selection</button></form>`;
      details.querySelector('form').addEventListener('submit',event=>{event.preventDefault();const selection=Object.fromEntries(new FormData(event.currentTarget));localStorage.setItem(`fc-store-${plan.id}`,JSON.stringify(selection));showToast('Your edition choices have been saved')});
      card.querySelector('.archive-product-copy').append(details);
    });
  }catch(error){if(!/Sign in/.test(error.message))showToast(error.message)}
}
async function protectAccountView(){if(location.pathname!=='/dashboard')return;try{const session=await apiRequest('/api/auth/session');if(!session.authenticated)route('/login?next=/dashboard',true)}catch{route('/login?next=/dashboard',true)}}
function bindPage(){
  if(location.pathname==='/dashboard')mountFamilyDashboard({route,apiRequest});
  document.querySelectorAll('[data-link]').forEach(link=>link.addEventListener('click',navigate));
  document.querySelector('#recordButton')?.addEventListener('click',e=>{const active=e.currentTarget.classList.toggle('recording');e.currentTarget.textContent=active?'Stop':'Speak';document.querySelector('#transcript').textContent=active?'Listening… Take your time.':'“The kitchen always smelled like cinnamon on Sunday mornings…”'});
  document.querySelectorAll('[data-billing]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-billing]').forEach(b=>b.classList.toggle('active',b===button));document.querySelectorAll('[data-price]').forEach(p=>p.textContent=p.dataset[button.dataset.billing]);document.querySelectorAll('[data-cycle]').forEach(p=>p.textContent=button.dataset.billing==='annual'?'per year':'per month')}));
  document.querySelectorAll('.add-cart').forEach(b=>b.addEventListener('click',()=>showToast(`${b.dataset.product} added to your cart`)));
  document.querySelectorAll('.read-story').forEach(b=>b.addEventListener('click',()=>showToast('Story preview coming soon')));
  document.querySelectorAll('.gift-action').forEach(b=>b.addEventListener('click',()=>showToast('Gift checkout will open after payment setup')));
  const journeyContent={speak:['A quiet prompt','“What did home feel like when you were ten?”','Tap once and answer in your own words. There is no timer and no perfect way to tell it.'],shape:['An editable draft','Your words, shaped into a story','Compare the recording, transcript, and suggested narrative. Correct facts and keep the phrasing that sounds like you.'],place:['A connected memory','People, year, and place come together','Link Mary, 1958, and Chicago. The story settles into the timeline and appears in Mary’s life profile.'],print:['A family-approved edition','Preview it before it becomes a book','Choose the photograph, chapter order, and visibility. The family owner approves the complete edition before printing.']};
  document.querySelectorAll('.journey-tab').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.journey-tab').forEach(x=>x.classList.toggle('active',x===b));const c=journeyContent[b.dataset.journey];document.querySelector('#journeyKicker').textContent=c[0];document.querySelector('#journeyTitle').textContent=c[1];document.querySelector('#journeyText').textContent=c[2];applyTranslations()}));
  const clientScreens={
    timeline:{label:'THE FAMILY HOME',title:'See the people and moments that shaped you.',text:'The opening screen is a story-led family timeline with quick ways to record a voice, add a photograph, invite someone, or preview the annual book.',link:'/features',html:`<div class="app-top"><div><small>Johnston Family · 23 members</small><b>FamilyChronica</b></div><button>MJ</button></div><div class="app-progress"><i></i></div><h3>Keep each other's stories<br>for the family ahead.</h3><div class="quick-actions"><span>●<small>Voice</small></span><span>▧<small>Photos</small></span><span>▶<small>Video</small></span><span>＋<small>Invite</small></span></div><div class="app-year">2026 · FAMILY TIMELINE</div><article class="app-story"><div class="story-thumb coral">▶</div><div><b>Grandma's 90th birthday</b><small>August 15 · 12 family contributors</small><em>Play film · 03:42</em></div></article><article class="app-story"><div class="story-thumb green">♪</div><div><b>Grandpa's old London</b><small>June 12 · Story draft reviewed</small><em>Continue listening · 52%</em></div></article>`},
    photos:{label:'SMART ALBUMS',title:'Turn an unlabelled camera roll into family history.',text:'Import photographs, review suggested people and places, organize shared albums, search by memory, and choose who may view or download each collection.',link:'/albums',html:`<div class="app-top"><div><small>Johnston Family</small><b>Albums</b></div><button>＋</button></div><h3>Photos become easier<br>to remember together.</h3><div class="scan-banner"><strong>42 photos ready to review</strong><span>Confirm AI suggestions →</span></div><div class="album-grid"><article><div class="album-img one"></div><b>All of us together</b><small>86 photos · 14 people</small></article><article><div class="album-img two"></div><b>Places we called home</b><small>34 photos · 5 places</small></article><article><div class="album-img three"></div><b>Roads we travelled</b><small>29 photos · 4 cars</small></article><article><div class="album-img four"></div><b>Grandma's birthday</b><small>18 photos · Private</small></article></div>`},
    interview:{label:'GUIDED INTERVIEW',title:'A gentle question is enough to begin.',text:'Choose spoken or typed answers, pause whenever needed, and return to a saved interview path covering childhood, family, work, migration, traditions, and values.',link:'/ai-interview',html:`<div class="app-top"><div><small>Guided interview · 3 of 12</small><b>Take your time. I'm listening.</b></div><button>×</button></div><div class="interview-orb">✦</div><p class="interview-question">What was the home you grew up in like?</p><div class="answer-box">“Our house was narrow, but the kitchen always felt large because everyone gathered there…”</div><div class="answer-actions"><button>● Record answer</button><button>✎ Type instead</button></div><div class="interview-progress"><i></i></div><small class="saved-note">Progress saved · Continue anytime</small>`},
    books:{label:'LIVING BOOKS',title:"Know exactly how this year's book is taking shape.",text:'See completion, estimated pages, included stories and media, preview the electronic edition, compare versions, and order or reprint the family-approved edition.',link:'/sample-book',html:`<div class="app-top"><div><small>Johnston Family</small><b>My Books</b></div><button>•••</button></div><div class="current-book"><span>2026</span><div><small>ANNUAL FAMILY CHRONICLE</small><b>Volume Four</b><em>Editing · 67% complete</em></div></div><div class="book-progress"><i></i></div><div class="book-metrics"><span><b>38</b> stories</span><span><b>127</b> photos</span><span><b>4</b> videos</span></div><button class="app-primary">Preview electronic edition</button><div class="version-row"><span>2025 · v3.0</span><strong>Published · 156 pages</strong></div><div class="version-row"><span>2024 · v2.1</span><strong>Available to reprint</strong></div>`}
  };
  document.querySelectorAll('.client-tab').forEach(b=>b.addEventListener('click',()=>{const c=clientScreens[b.dataset.clientScreen];document.querySelectorAll('.client-tab').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#clientLabel').textContent=c.label;document.querySelector('#clientTitle').textContent=c.title;document.querySelector('#clientText').textContent=c.text;document.querySelector('#clientLink').setAttribute('href',c.link);document.querySelector('#appScreen').innerHTML=c.html;applyTranslations()}));
  document.querySelectorAll('[data-demo-form]').forEach(f=>f.addEventListener('submit',e=>{e.preventDefault();showToast('Your secure preview is ready');setTimeout(()=>route('/dashboard'),700)}));
  document.querySelector('#newMemory')?.addEventListener('click',()=>showToast('Memory recorder opened'));
  document.querySelector('#emailLoginForm')?.addEventListener('submit',async e=>{e.preventDefault();const email=document.querySelector('#loginEmail').value;const button=e.currentTarget.querySelector('button');button.disabled=true;try{await apiRequest('/api/auth/request-code',{method:'POST',body:JSON.stringify({email,intent:'login'})});document.querySelector('#sentEmail').textContent=email;document.querySelector('#emailStep').classList.add('hidden');document.querySelector('#codeStep').classList.remove('hidden');document.querySelector('.code-inputs input')?.focus()}catch(error){showToast(error.message)}finally{button.disabled=false}});
  document.querySelector('#backToEmail')?.addEventListener('click',()=>{document.querySelector('#codeStep').classList.add('hidden');document.querySelector('#emailStep').classList.remove('hidden')});
  document.querySelectorAll('.code-inputs input').forEach((input,index,all)=>input.addEventListener('input',()=>{input.value=input.value.replace(/\D/g,'').slice(0,1);if(input.value&&all[index+1])all[index+1].focus()}));
  document.querySelector('#codeLoginForm')?.addEventListener('submit',async e=>{e.preventDefault();const email=document.querySelector('#loginEmail').value;const code=[...document.querySelectorAll('.code-inputs input')].map(input=>input.value).join('');try{await apiRequest('/api/auth/verify-code',{method:'POST',body:JSON.stringify({email,code,intent:'login'})});showToast('Sign-in confirmed');const next=new URLSearchParams(location.search).get('next');setTimeout(()=>route(next&&next.startsWith('/')?next:'/dashboard'),350)}catch(error){showToast(error.message)}});
  document.querySelector('#resendCode')?.addEventListener('click',async()=>{try{await apiRequest('/api/auth/request-code',{method:'POST',body:JSON.stringify({email:document.querySelector('#loginEmail').value,intent:'login'})});showToast('A new code has been sent')}catch(error){showToast(error.message)}});
  document.querySelector('#registerEmailForm')?.addEventListener('submit',async e=>{e.preventDefault();const status=document.querySelector('#registerStatus');const email=document.querySelector('#registerEmail').value;status.textContent='Sending your secure code…';try{await apiRequest('/api/auth/request-code',{method:'POST',body:JSON.stringify({email,intent:'register'})});document.querySelector('#registerSentEmail').textContent=email;document.querySelector('#registerDetails').classList.add('hidden');document.querySelector('#registerCodeStep').classList.remove('hidden');document.querySelector('#registerCode').focus()}catch(error){status.textContent=error.message}});
  document.querySelector('#backToRegister')?.addEventListener('click',()=>{document.querySelector('#registerCodeStep').classList.add('hidden');document.querySelector('#registerDetails').classList.remove('hidden')});
  document.querySelector('#registerCodeForm')?.addEventListener('submit',async e=>{e.preventDefault();const status=document.querySelector('#registerCodeStatus');status.textContent='Creating your private family account…';try{await apiRequest('/api/auth/verify-code',{method:'POST',body:JSON.stringify({email:document.querySelector('#registerEmail').value,code:document.querySelector('#registerCode').value,intent:'register',name:document.querySelector('#registerName').value,familyName:document.querySelector('#registerFamily').value})});showToast('Your family account is ready');setTimeout(()=>route('/dashboard'),350)}catch(error){status.textContent=error.message}});
  document.querySelector('#joinFamilyButton')?.addEventListener('click',()=>showToast('Invitation code entry will open here'));
  document.querySelector('#signOutButton')?.addEventListener('click',async()=>{try{await apiRequest('/api/auth/logout',{method:'POST'})}finally{route('/login')}});
  const workspaceViews={timeline:['Family timeline','Every shared moment, in order.','Browse voice stories, photographs, videos, milestones, and family contributions by year.'],stories:['Stories & interviews','Record, review, and shape every voice.','Continue guided interviews, compare source recordings with drafts, and approve stories for the family edition.'],albums:['Albums','Photographs with people and context.','Review scanned photographs, correct suggested labels, organize albums, and set who may view or download them.'],tree:['Family tree','Every person has a place in the story.','Explore relationships and open a member profile to find their stories, photographs, audio, and video.'],books:['My books','From this year’s draft to every edition.','Preview the 2026 chronicle, compare versions, approve print files, or order a historical reprint.'],members:['Family members','Invite carefully. Share deliberately.','Manage owners, editors, contributors, viewers, pending invitations, and memory-level access.'],orders:['Orders','Printed memories on their way.','Track book approval, production, shipment, delivery, and available reorders.'],settings:['Settings','Your account and family preferences.','Manage language, text size, privacy, AI recognition, data export, subscription, support, and account access.']};
  document.querySelectorAll('.workspace-nav button,.sidebar-bottom>button').forEach(b=>b.addEventListener('click',()=>{if(b.dataset.workspace==='overview')return route('/dashboard');const c=workspaceViews[b.dataset.workspace];if(!c)return;document.querySelectorAll('.workspace-nav button,.sidebar-bottom>button').forEach(x=>x.classList.toggle('active',x===b));document.querySelector('#workspaceName').textContent=c[0].toUpperCase();document.querySelector('#workspaceHeading').textContent=c[0];document.querySelector('#workspaceContent').innerHTML=`<section class="workspace-empty"><span class="eyebrow">${c[0]}</span><h2>${c[1]}</h2><p>${c[2]}</p><div class="workspace-placeholder"><div></div><div></div><div></div></div><button class="button workspace-demo-action">Open ${c[0]}</button></section>`;document.querySelector('.workspace-demo-action').addEventListener('click',()=>showToast(`${c[0]} workspace is ready for backend connection`))}));
  loadStoreAccess();
  protectAccountView();
}
function navigate(event){const url=new URL(event.currentTarget.href,location.origin);if(url.origin!==location.origin)return;event.preventDefault();route(`${url.pathname}${url.search}`)}
function route(path,replace=false){releaseDashboardMedia();history[replace?'replaceState':'pushState']({},'',path);render()}
function render(){const path=location.pathname.replace(/\/$/,'')||'/';document.body.className=document.body.className.replace(/\broute-[\w-]+\b/g,'').trim();document.body.classList.add(`route-${path.slice(1)||'home'}`);main.innerHTML=(pages[path]||pages['/'])();applySeo(path);document.querySelectorAll('.desktop-nav a').forEach(a=>a.classList.toggle('active',new URL(a.href).pathname===path));document.querySelector('#mobileNav').classList.remove('open');window.scrollTo(0,0);bindPage();applyTranslations();document.querySelectorAll('#languageSelect,.language-select').forEach(select=>select.addEventListener('change',event=>setLanguage(event.target.value)))}

document.querySelector('#fontToggle').addEventListener('click',()=>{document.body.classList.toggle('large-text');localStorage.setItem('fc-large-text',document.body.classList.contains('large-text'))});
document.querySelector('#menuButton').addEventListener('click',e=>{const open=document.querySelector('#mobileNav').classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',String(open))});
if(localStorage.getItem('fc-large-text')==='true')document.body.classList.add('large-text');
document.querySelector('#languageSelect').value=getLanguage();
addEventListener('popstate',()=>{releaseDashboardMedia();render()});render();
